import{_ as a}from"./chunks/dispatch-week.BMCYSnKC.js";import{_ as t,o as s,c as r,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const _=JSON.parse('{"title":"Πρόγραμμα αναθέσεων","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/dispatch-schedule.md","filePath":"el/plus/dispatch-schedule.md"}'),l={name:"el/plus/dispatch-schedule.md"};function i(n,e,h,c,p,d){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="προγραμμα-αναθεσεων" tabindex="-1">Πρόγραμμα αναθέσεων <a class="header-anchor" href="#προγραμμα-αναθεσεων" aria-label="Permalink to &quot;Πρόγραμμα αναθέσεων&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Πηγαίος κώδικας TransferBook+ v0.7.9. Το παρόν είναι τοπικό προσχέδιο προς έλεγχο, όχι επιβεβαίωση διαθεσιμότητας στην παραγωγή. Ελέγξτε την εγκατεστημένη έκδοση και τα δικαιώματά σας.</p></div><h2 id="εικονογραφημενη-προβολη" tabindex="-1">Εικονογραφημένη προβολή <a class="header-anchor" href="#εικονογραφημενη-προβολη" aria-label="Permalink to &quot;Εικονογραφημένη προβολή&quot;">​</a></h2><p><a href="/screenshots/v0.7.11/dispatch-week.png"><img src="'+a+'" alt="Εβδομαδιαία προβολή αναθέσεων: χρησιμοποιήστε τα Day, Week ή Month, την επιλογή ημερομηνίας και το φίλτρο κατάστασης."></a></p><p><em>Επιλέξτε την εικόνα για προβολή στο αρχικό της μέγεθος. Επιστρέψτε με το κουμπί Πίσω του προγράμματος περιήγησης.</em></p><p><em>Εβδομαδιαία προβολή αναθέσεων: χρησιμοποιήστε τα Day, Week ή Month, την επιλογή ημερομηνίας και το φίλτρο κατάστασης.</em></p><p>Λήψη από περιβάλλον δοκιμών, TransferBook+ v0.7.11· αγγλικό περιβάλλον. Ενδεικτικά δοκιμαστικά στοιχεία. Η εικόνα δεν αποδεικνύει διαθεσιμότητα στην παραγωγή. Έχουν καλυφθεί αναγνωριστικά στοιχεία.</p><h2 id="σκοπος-και-προσβαση" tabindex="-1">Σκοπός και πρόσβαση <a class="header-anchor" href="#σκοπος-και-προσβαση" aria-label="Permalink to &quot;Σκοπός και πρόσβαση&quot;">​</a></h2><p>Το ημερολόγιο αναθέσεων παρέχει προβολές ημέρας, εβδομάδας και μήνα για έλεγχο του φόρτου από εξουσιοδοτημένο χειριστή.</p><h2 id="διαδικασια" tabindex="-1">Διαδικασία <a class="header-anchor" href="#διαδικασια" aria-label="Permalink to &quot;Διαδικασία&quot;">​</a></h2><ol><li>Ανοίξτε <strong>Dispatch Timeline &amp; Daily Schedule</strong> ή την προβολή ημερολογίου.</li><li>Επιλέξτε ημέρα, εβδομάδα ή μήνα, τη σχετική περίοδο και την περιοχή.</li><li>Χρησιμοποιήστε τα φίλτρα <strong>All statuses</strong>, <strong>Quote required</strong>, <strong>Tour acceptance pending</strong>, <strong>Dispatch review</strong>, <strong>Assigned / In transit</strong> ή <strong>Completed / Cancelled</strong>.</li><li>Ελέγξτε τις προγραμματισμένες παραλαβές χρονικά και ανοίξτε τις λεπτομέρειες πριν από ανάθεση.</li><li>Ελέγξτε οδηγό, όχημα, χωρητικότητα, περιοχή και επικαλύψεις πριν από ανάθεση μέσω των εγκεκριμένων εργαλείων.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Η επιλεγμένη περίοδος και τα φίλτρα εμφανίζουν τις αντίστοιχες κρατήσεις. Οι εκκρεμείς προσφορές ή έλεγχοι δεν σημαίνουν ετοιμότητα ανάθεσης.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Ελέγξτε περιοχή, περίοδο και φίλτρο αν λείπει διαδρομή. Αν απορρίπτεται ανάθεση, επιλύστε τις συγκρούσεις. Δείτε την <a href="/el/plus/assignments.html">ανάθεση οδηγού και οχήματος</a>.</p>',15)])])}const f=t(l,[["render",i]]);export{_ as __pageData,f as default};
